// Roboto Latin WOFF assets from @fontsource/roboto (Apache-2.0).
export const ROBOTO_REGULAR_BASE64 = "";
export const ROBOTO_BOLD_BASE64 = "";
export const ROBOTO_ITALIC_BASE64 = "";

export function decodeFont(base64: string): Uint8Array {
  const binary = atob(base64);
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}

